

class SimWorkspace {
    constructor() {
        this.currentPresetKey = 'university';
        this.relationR = null;
        this.relationS = null;
        this.executionTrace = null;
        this.sqlObj = null;
        this.isExactMode = false;
        this.fuzzyThreshold = 75;
        this.pipelineDebounceTimer = null;
        this.terminal = new TechTerminal('sim-terminal');

        this.init();
    }

    init() {
        window.simWorkspace = this;
        window.simApp = this;
        if (typeof TechLayout !== 'undefined') {
            TechLayout.mount('simulation');
        }

        this.terminal.log('Obsidian Simulation Workspace online.', 'info');
        this.terminal.log('Subsystems online: Relational Division Engine, AST Visualizer, SQL Dialect Studio, Tuple Tracer.', 'info');

        const urlParams = new URLSearchParams(window.location.search);
        const presetParam = urlParams.get('preset') || localStorage.getItem('relational_div_selected_preset');
        if (presetParam && typeof PRESETS !== 'undefined' && PRESETS[presetParam]) {
            this.currentPresetKey = presetParam;
            localStorage.removeItem('relational_div_selected_preset');
        }

        this.bindEvents();

        const importedDataRaw = sessionStorage.getItem('rel_div_import_data');
        if (importedDataRaw) {
            try {
                const imp = JSON.parse(importedDataRaw);
                sessionStorage.removeItem('rel_div_import_data');
                this.loadCustomData(imp.rName, imp.rAttrs, imp.rTuples, imp.sName, imp.sAttrs, imp.sTuples);
                this.handleHashChange();
                return;
            } catch(e) {}
        }

        const chalId = urlParams.get('loadChal');
        if (chalId && typeof AIPractice !== 'undefined') {
            const chal = AIPractice.challenges.find(c => c.id === chalId);
            if (chal) {
                this.loadCustomData(chal.rName, chal.rAttrs, chal.rTuples, chal.sName, chal.sAttrs, chal.sTuples);
                this.handleHashChange();
                return;
            }
        }

        this.loadPreset(this.currentPresetKey);
        this.handleHashChange();
    }

    bindEvents() {
        document.querySelectorAll('.center-tab-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const viewKey = btn.getAttribute('data-view');
                if (viewKey) {
                    window.location.hash = viewKey;
                    this.switchCenterView(viewKey);
                }
            });
        });

        document.querySelectorAll('.quick-preset-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const presetKey = btn.getAttribute('data-preset');
                if (presetKey) {
                    this.loadPreset(presetKey);
                }
            });
        });

        const quickRunBtn = document.getElementById('quick-btn-run');
        if (quickRunBtn) {
            quickRunBtn.addEventListener('click', () => {
                this.executePipeline();
                if (typeof toast !== 'undefined') {
                    toast.success('Relational Division pipeline executed.');
                }
            });
        }

        const quickExportBtn = document.getElementById('quick-btn-export');
        if (quickExportBtn) {
            quickExportBtn.addEventListener('click', () => {
                window.triggerReportDownload();
            });
        }

        const pSelect = document.getElementById('preset-selector');
        if (pSelect) {
            pSelect.addEventListener('change', (e) => this.loadPreset(e.target.value));
        }

        const runBtn = document.getElementById('btn-run-sim');
        if (runBtn) {
            runBtn.addEventListener('click', () => {
                this.executePipeline();
                if (typeof toast !== 'undefined') {
                    toast.success('Relational Division pipeline executed successfully.');
                }
            });
        }

        window.addEventListener('keydown', (e) => {
            if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
                e.preventDefault();
                if (document.activeElement && document.activeElement.matches('input[data-table]')) {
                    const input = document.activeElement;
                    const tbl = input.getAttribute('data-table');
                    const row = parseInt(input.getAttribute('data-row'), 10);
                    const attr = input.getAttribute('data-attr');
                    if (tbl === 'R' && this.relationR?.tuples[row]) {
                        this.relationR.tuples[row][attr] = input.value.trim();
                    } else if (tbl === 'S' && this.relationS?.tuples[row]) {
                        this.relationS.tuples[row][attr] = input.value.trim();
                    }
                }
                this.executePipeline();
                if (typeof toast !== 'undefined') {
                    toast.success('Pipeline executed via shortcut [Ctrl+Enter]');
                }
            }
        });

        const toggleExact = document.getElementById('toggle-exact-mode');
        if (toggleExact) {
            toggleExact.addEventListener('change', (e) => {
                this.isExactMode = e.target.checked;
                if (this.isExactMode) {
                    this.terminal.log('Exact division mode ($R \\div_{exact} S$) ACTIVE: Enforcing strict bijection (zero superfluous tuples).', 'warn');
                    if (typeof toast !== 'undefined') toast.info('Exact Division (R ÷_exact S) ENABLED: Candidates with extra tuples eliminated');
                } else {
                    this.terminal.log('Standard division mode ($R \\div S$) ACTIVE: Supersets permitted.', 'info');
                    if (typeof toast !== 'undefined') toast.info('Standard Division (R ÷ S) RESTORED: Supersets allowed');
                }
                this.executePipeline();
            });
        }

        const slider = document.getElementById('slider-threshold');
        if (slider) {
            slider.addEventListener('input', (e) => {
                this.fuzzyThreshold = parseInt(e.target.value, 10);
                const lbl = document.getElementById('label-threshold');
                if (lbl) lbl.textContent = `${this.fuzzyThreshold}%`;
                const tabBadgeMatrix = document.getElementById('tab-badge-matrix');
                if (tabBadgeMatrix) tabBadgeMatrix.textContent = `${this.fuzzyThreshold}%`;
                this.updateCoverageMatrix();
            });
        }

        document.getElementById('btn-open-importer')?.addEventListener('click', () => {
            if (typeof UniversalImporter !== 'undefined') UniversalImporter.openModal();
        });
        document.getElementById('btn-open-exams-sidebar')?.addEventListener('click', () => {
            if (typeof CompetitiveExams !== 'undefined') CompetitiveExams.openModal();
        });
        document.getElementById('btn-open-practice-sidebar')?.addEventListener('click', () => {
            if (typeof AIPractice !== 'undefined') AIPractice.openModal();
        });

        document.getElementById('btn-add-r')?.addEventListener('click', () => this.addRowR());
        document.getElementById('btn-add-s')?.addEventListener('click', () => this.addRowS());

        document.getElementById('btn-export-csv-r')?.addEventListener('click', () => {
            if (typeof ReportGenerator !== 'undefined') {
                ReportGenerator.downloadCSV(this.relationR, `${this.relationR.name}.csv`);
                if (typeof toast !== 'undefined') toast.info(`Exported ${this.relationR.name}.csv`);
            }
        });
        document.getElementById('btn-export-csv-s')?.addEventListener('click', () => {
            if (typeof ReportGenerator !== 'undefined') {
                ReportGenerator.downloadCSV(this.relationS, `${this.relationS.name}.csv`);
                if (typeof toast !== 'undefined') toast.info(`Exported ${this.relationS.name}.csv`);
            }
        });
        document.getElementById('btn-export-result-csv')?.addEventListener('click', () => {
            const targetRel = this.isExactMode ? this.executionTrace?.exactResult : this.executionTrace?.T5;
            if (targetRel && typeof ReportGenerator !== 'undefined') {
                ReportGenerator.downloadCSV(targetRel, `Result_Division.csv`);
                if (typeof toast !== 'undefined') toast.info(`Exported Result_Division.csv`);
            }
        });

        document.getElementById('btn-clear-term')?.addEventListener('click', () => this.terminal.clear());

        document.querySelectorAll('.btn-copy-code').forEach(btn => {
            btn.addEventListener('click', () => {
                const targetId = btn.getAttribute('data-target');
                const text = document.getElementById(targetId)?.textContent;
                if (text) {
                    navigator.clipboard.writeText(text);
                    const originalText = btn.textContent;
                    btn.textContent = '✓ Copied';
                    setTimeout(() => btn.textContent = originalText, 1800);
                    if (typeof toast !== 'undefined') toast.info('SQL query copied to clipboard.');
                }
            });
        });

        document.getElementById('btn-retest')?.addEventListener('click', () => this.runTests());

        window.triggerReportDownload = () => {
            const modal = document.getElementById('global-export-modal');
            if (modal) {
                modal.classList.add('open');
            } else if (typeof ReportGenerator !== 'undefined') {
                ReportGenerator.printPDF(this.executionTrace, this.relationR, this.relationS, this.sqlObj);
            }
        };

        window.addEventListener('hashchange', () => this.handleHashChange());
    }

    handleHashChange() {
        const hash = window.location.hash.replace('#', '') || 'result';
        if (hash === 'download') {
            window.triggerReportDownload();
            if (window.history && window.history.replaceState) {
                window.history.replaceState(null, '', window.location.pathname + '#result');
            }
            this.switchCenterView('result');
        } else if (hash === 'workspace') {
            this.switchCenterView('result');
        } else if (['result', 'dag', 'steps', 'tracer', 'sql', 'matrix', 'tests'].includes(hash)) {
            this.switchCenterView(hash);
        }
    }

    switchCenterView(viewKey) {
        document.querySelectorAll('.center-tab-btn').forEach(b => {
            if (b.getAttribute('data-view') === viewKey) {
                b.classList.add('active');
            } else {
                b.classList.remove('active');
            }
        });

        document.querySelectorAll('.center-view').forEach(v => {
            if (v.id === `view-${viewKey}`) {
                v.classList.remove('hidden');
            } else {
                v.classList.add('hidden');
            }
        });

        document.querySelectorAll('.sidenav-item').forEach(item => {
            const href = item.getAttribute('href') || '';
            if (href.includes(`#${viewKey}`)) {
                item.classList.add('active');
            } else if (href.includes('simulation.html#')) {
                item.classList.remove('active');
            }
        });

        if (viewKey === 'dag' && this.executionTrace) {
            Visualizer.renderDAG(document.getElementById('container-dag'), this.executionTrace, this.isExactMode);
        } else if (viewKey === 'tests') {
            this.runTests();
        } else if (viewKey === 'matrix') {
            this.updateCoverageMatrix();
        }

        if (typeof renderMathInElement !== 'undefined') {
            try {
                renderMathInElement(document.body, {delimiters: [{left: '$$', right: '$$', display: true}, {left: '$', right: '$', display: false}]});
            } catch (e) {}
        }
    }

    loadPreset(presetKey) {
        const p = PRESETS[presetKey];
        if (!p) return;

        this.currentPresetKey = presetKey;
        
        document.querySelectorAll('.quick-preset-btn').forEach(b => {
            if (b.getAttribute('data-preset') === presetKey) {
                b.classList.add('active');
            } else {
                b.classList.remove('active');
            }
        });

        const pSelect = document.getElementById('preset-selector');
        if (pSelect && pSelect.value !== presetKey) {
            pSelect.value = presetKey;
        }

        this.relationR = new Relation(p.rName, p.rAttrs, p.rTuples);
        this.relationS = new Relation(p.sName, p.sAttrs, p.sTuples);

        const rSchema = document.getElementById('label-r-schema');
        const sSchema = document.getElementById('label-s-schema');
        if (rSchema) rSchema.textContent = `Schema: (${p.rAttrs.join(', ')})`;
        if (sSchema) sSchema.textContent = `Schema: (${p.sAttrs.join(', ')})`;

        this.renderTableR();
        this.renderTableS();
        this.executePipeline();

        this.terminal.log(`Loaded scenario: ${p.title}`, 'info');
    }

    loadCustomData(rName, rAttrs, rTuples, sName, sAttrs, sTuples) {
        this.relationR = new Relation(rName || 'CustomDividend_R', rAttrs, rTuples);
        this.relationS = new Relation(sName || 'CustomDivisor_S', sAttrs, sTuples);

        const rSchema = document.getElementById('label-r-schema');
        const sSchema = document.getElementById('label-s-schema');
        if (rSchema) rSchema.textContent = `Schema: (${rAttrs.join(', ')})`;
        if (sSchema) sSchema.textContent = `Schema: (${sAttrs.join(', ')})`;

        this.renderTableR();
        this.renderTableS();
        this.executePipeline();

        this.terminal.log(`Loaded custom dataset: ${rName} (${rTuples.length} rows) ÷ ${sName} (${sTuples.length} rows)`, 'success');
        if (typeof toast !== 'undefined') toast.success(`Custom dataset loaded & division computed!`);
    }

    executePipelineDebounced() {
        if (this.pipelineDebounceTimer) clearTimeout(this.pipelineDebounceTimer);
        this.pipelineDebounceTimer = setTimeout(() => {
            this.executePipeline();
        }, 120);
    }

    renderTableR() {
        const container = document.getElementById('container-table-r');
        if (!container) return;
        const countBadge = document.getElementById('badge-r-count');
        if (countBadge) countBadge.textContent = `${this.relationR.cardinality} rows`;

        let html = `
            <table class="w-full text-left border-collapse text-xs">
                <thead>
                    <tr class="border-b border-gray-200 dark:border-[#1f1f29] bg-lightPrimary/50 dark:bg-[#101018]">
                        <th class="py-2.5 px-2.5 text-center text-[10px] font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider w-7">#</th>
        `;
        this.relationR.attributes.forEach(attr => {
            html += `<th class="py-2.5 px-2.5 text-[10px] font-bold text-gray-600 dark:text-gray-300 uppercase tracking-wider font-mono">${attr}</th>`;
        });
        html += `<th class="py-2.5 px-2.5 text-center text-[10px] font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider w-7">✕</th></tr></thead>
        <tbody class="divide-y divide-gray-100 dark:divide-[#181822] bg-white dark:bg-[#0e0e14]">`;

        this.relationR.tuples.forEach((t, i) => {
            html += `<tr class="hover:bg-lightPrimary/60 dark:hover:bg-[#181822] transition-colors">
                <td class="py-1.5 px-2.5 text-center text-[11px] text-gray-400 font-mono">${i + 1}</td>`;
            this.relationR.attributes.forEach(attr => {
                html += `
                    <td class="py-1 px-2.5">
                        <input type="text"
                               class="w-full bg-transparent text-navy-700 dark:text-white font-medium text-xs rounded-lg px-2 py-1 border border-transparent hover:border-gray-200 dark:hover:border-[#252538] focus:border-[#7551FF] focus:bg-white dark:focus:bg-[#181824] outline-none transition-all font-mono"
                               value="${t[attr] !== undefined ? t[attr] : ''}"
                               data-table="R"
                               data-row="${i}"
                               data-attr="${attr}">
                    </td>
                `;
            });
            html += `
                <td class="py-1 px-2.5 text-center">
                    <button class="w-6 h-6 flex items-center justify-center rounded-lg text-gray-400 hover:text-[#EE5D50] hover:bg-[#EE5D50]/15 transition-colors delete-row-r-btn font-bold text-xs" data-row="${i}" title="Delete Row">✕</button>
                </td>
            </tr>`;
        });

        html += `</tbody></table>`;
        container.innerHTML = html;

        container.querySelectorAll('input').forEach(input => {
            input.addEventListener('input', (e) => {
                const row = parseInt(e.target.getAttribute('data-row'), 10);
                const attr = e.target.getAttribute('data-attr');
                if (this.relationR.tuples[row]) {
                    this.relationR.tuples[row][attr] = e.target.value.trim();
                    this.executePipelineDebounced();
                }
            });
            input.addEventListener('change', (e) => {
                const row = parseInt(e.target.getAttribute('data-row'), 10);
                const attr = e.target.getAttribute('data-attr');
                if (this.relationR.tuples[row]) {
                    this.relationR.tuples[row][attr] = e.target.value.trim();
                    this.executePipeline();
                }
            });
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.ctrlKey && !e.metaKey) {
                    e.target.blur();
                }
            });
        });

        container.querySelectorAll('.delete-row-r-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const row = parseInt(btn.getAttribute('data-row'), 10);
                this.deleteRowR(row);
            });
        });
    }

    renderTableS() {
        const container = document.getElementById('container-table-s');
        if (!container) return;
        const countBadge = document.getElementById('badge-s-count');
        if (countBadge) countBadge.textContent = `${this.relationS.cardinality} rows`;

        let html = `
            <table class="w-full text-left border-collapse text-xs">
                <thead>
                    <tr class="border-b border-gray-200 dark:border-[#1f1f29] bg-lightPrimary/50 dark:bg-[#101018]">
                        <th class="py-2.5 px-2.5 text-center text-[10px] font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider w-7">#</th>
        `;
        this.relationS.attributes.forEach(attr => {
            html += `<th class="py-2.5 px-2.5 text-[10px] font-bold text-gray-600 dark:text-gray-300 uppercase tracking-wider font-mono">${attr}</th>`;
        });
        html += `<th class="py-2.5 px-2.5 text-center text-[10px] font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider w-7">✕</th></tr></thead>
        <tbody class="divide-y divide-gray-100 dark:divide-[#181822] bg-white dark:bg-[#0e0e14]">`;

        this.relationS.tuples.forEach((t, i) => {
            html += `<tr class="hover:bg-lightPrimary/60 dark:hover:bg-[#181822] transition-colors">
                <td class="py-1.5 px-2.5 text-center text-[11px] text-gray-400 font-mono">${i + 1}</td>`;
            this.relationS.attributes.forEach(attr => {
                html += `
                    <td class="py-1 px-2.5">
                        <input type="text"
                               class="w-full bg-transparent text-navy-700 dark:text-white font-medium text-xs rounded-lg px-2 py-1 border border-transparent hover:border-gray-200 dark:hover:border-[#252538] focus:border-[#7551FF] focus:bg-white dark:focus:bg-[#181824] outline-none transition-all font-mono"
                               value="${t[attr] !== undefined ? t[attr] : ''}"
                               data-table="S"
                               data-row="${i}"
                               data-attr="${attr}">
                    </td>
                `;
            });
            html += `
                <td class="py-1 px-2.5 text-center">
                    <button class="w-6 h-6 flex items-center justify-center rounded-lg text-gray-400 hover:text-[#EE5D50] hover:bg-[#EE5D50]/15 transition-colors delete-row-s-btn font-bold text-xs" data-row="${i}" title="Delete Row">✕</button>
                </td>
            </tr>`;
        });

        html += `</tbody></table>`;
        container.innerHTML = html;

        container.querySelectorAll('input').forEach(input => {
            input.addEventListener('input', (e) => {
                const row = parseInt(e.target.getAttribute('data-row'), 10);
                const attr = e.target.getAttribute('data-attr');
                if (this.relationS.tuples[row]) {
                    this.relationS.tuples[row][attr] = e.target.value.trim();
                    this.executePipelineDebounced();
                }
            });
            input.addEventListener('change', (e) => {
                const row = parseInt(e.target.getAttribute('data-row'), 10);
                const attr = e.target.getAttribute('data-attr');
                if (this.relationS.tuples[row]) {
                    this.relationS.tuples[row][attr] = e.target.value.trim();
                    this.executePipeline();
                }
            });
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.ctrlKey && !e.metaKey) {
                    e.target.blur();
                }
            });
        });

        container.querySelectorAll('.delete-row-s-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const row = parseInt(btn.getAttribute('data-row'), 10);
                this.deleteRowS(row);
            });
        });
    }

    deleteRowR(i) {
        this.relationR.tuples.splice(i, 1);
        this.renderTableR();
        this.executePipeline();
    }

    deleteRowS(i) {
        this.relationS.tuples.splice(i, 1);
        this.renderTableS();
        this.executePipeline();
    }

    addRowR() {
        const newT = {};
        const count = this.relationR.cardinality + 1;
        this.relationR.attributes.forEach((a, idx) => {
            newT[a] = idx === 0 ? `New_${count}` : 'Val';
        });
        this.relationR.tuples.push(newT);
        this.renderTableR();
        this.executePipeline();
        if (typeof toast !== 'undefined') toast.info('Inserted row into Relation R');
    }

    addRowS() {
        const newT = {};
        const count = this.relationS.cardinality + 1;
        this.relationS.attributes.forEach((a, idx) => {
            newT[a] = `Req_${count}`;
        });
        this.relationS.tuples.push(newT);
        this.renderTableS();
        this.executePipeline();
        if (typeof toast !== 'undefined') toast.info('Inserted row into Relation S');
    }

    executePipeline() {
        try {
            const start = performance.now();
            this.executionTrace = this.isExactMode
                ? RelationalDivisionEngine.divideExact(this.relationR, this.relationS)
                : RelationalDivisionEngine.divide(this.relationR, this.relationS);

            const elapsed = (performance.now() - start).toFixed(2);
            const { T1, T2, T3, T4, T5, candidateAttrs, divisorAttrs, metrics, candidateAudit } = this.executionTrace;


            const elBadgeLat = document.getElementById('badge-lat');
            const elKpiLat = document.getElementById('kpi-latency');
            const elKpiCand = document.getElementById('kpi-candidates');
            const elKpiQual = document.getElementById('kpi-qualified');
            const elKpiDisqual = document.getElementById('kpi-disqualified');

            if (elBadgeLat) elBadgeLat.textContent = `${elapsed}ms`;
            if (elKpiLat) elKpiLat.textContent = `${elapsed} ms`;
            if (elKpiCand) elKpiCand.textContent = metrics.totalCandidates;
            if (elKpiQual) elKpiQual.textContent = metrics.qualifiedCount;
            if (elKpiDisqual) elKpiDisqual.textContent = metrics.disqualifiedCount;

            const qualCount = this.isExactMode ? this.executionTrace.exactQualifiedCount : metrics.qualifiedCount;
            const elBadgeQual = document.getElementById('badge-qual-count');
            const elResultStatus = document.getElementById('result-status-pill');
            const quickStatusLabel = document.getElementById('quick-status-label');

            if (elBadgeQual) elBadgeQual.textContent = `${qualCount} Qualified`;
            if (quickStatusLabel) quickStatusLabel.textContent = `${qualCount} QUALIFIED`;

            const elTabResult = document.getElementById('tab-badge-result');
            if (elTabResult) elTabResult.textContent = `${qualCount}`;

            const elTabTracer = document.getElementById('tab-badge-tracer');
            if (elTabTracer) elTabTracer.textContent = `${metrics.totalCandidates} Cand`;

            const elTabMatrix = document.getElementById('tab-badge-matrix');
            if (elTabMatrix) elTabMatrix.textContent = `${this.fuzzyThreshold}%`;

            const displayResult = this.isExactMode ? this.executionTrace.exactResult : T5;
            const resultTableContainer = document.getElementById('container-result-table');
            if (resultTableContainer) {
                resultTableContainer.innerHTML = Visualizer.renderTableHTML(displayResult, {
                    highlightRows: displayResult.tuples.map((_, i) => i)
                });
            }

            const elExactBanner = document.getElementById('exact-mode-banner');
            const elExactAudit = document.getElementById('container-exact-audit');
            const elResultHeading = document.getElementById('result-heading');
            const elResultSubheading = document.getElementById('result-subheading');
            const elResultIconBox = document.getElementById('result-icon-box');

            const universalQualifiers = candidateAudit.filter(c => c.isQualified);
            const droppedSupersets = universalQualifiers.filter(c => !c.isExactQualified);

            if (this.isExactMode) {
                if (elResultHeading) elResultHeading.textContent = `Exact Division Result // R ÷_exact S (${qualCount} Qualified)`;
                if (elResultSubheading) elResultSubheading.textContent = 'Strict Bijection: Only entities with all divisor items AND zero extra records qualify.';
                if (elResultStatus) {
                    elResultStatus.textContent = `${qualCount} EXACT QUALIFIED`;
                    elResultStatus.className = 'px-3 py-1 rounded-full text-xs font-bold bg-purple-500/20 text-[#C0B8FE] border border-[#7551FF]/40 font-mono';
                }
                if (elResultIconBox) {
                    elResultIconBox.className = 'w-8 h-8 rounded-xl bg-purple-500/15 flex items-center justify-center text-[#A195FD] border border-[#7551FF]/30';
                }

                if (elExactBanner) {
                    elExactBanner.classList.remove('hidden');
                    elExactBanner.className = 'p-3.5 rounded-xl bg-purple-500/15 border border-[#7551FF]/40 text-xs font-mono text-purple-200 flex flex-col sm:flex-row sm:items-center justify-between gap-2';
                    elExactBanner.innerHTML = `
                        <div class="flex items-center gap-2">
                            <span class="w-2.5 h-2.5 rounded-full bg-purple-400 animate-pulse"></span>
                            <span><strong>EXACT DIVISION ACTIVE:</strong> Strict bijection enforced. Zero superfluous tuples permitted.</span>
                        </div>
                        <span class="px-2.5 py-0.5 rounded-full bg-purple-500/25 text-[#C0B8FE] font-bold text-[11px] shrink-0 border border-purple-400/30">
                            ${droppedSupersets.length} superset candidate${droppedSupersets.length === 1 ? '' : 's'} eliminated
                        </span>
                    `;
                }
            } else {
                if (elResultHeading) elResultHeading.textContent = `Final Result Relation // T5 = R ÷ S (${qualCount} Qualified)`;
                if (elResultSubheading) elResultSubheading.textContent = 'Standard Codd Division: Universally qualified entities (candidates with extra electives/skills permitted).';
                if (elResultStatus) {
                    elResultStatus.textContent = `${qualCount} QUALIFIED`;
                    elResultStatus.className = 'px-3 py-1 rounded-full text-xs font-bold bg-green-500/10 text-[#05CD99] border border-[#05CD99]/20 font-mono';
                }
                if (elResultIconBox) {
                    elResultIconBox.className = 'w-8 h-8 rounded-xl bg-green-500/10 flex items-center justify-center text-[#05CD99] border border-[#05CD99]/20';
                }
                if (elExactBanner) {
                    elExactBanner.classList.add('hidden');
                }
            }

            if (elExactAudit) {
                let auditHtml = `
                    <div class="flex items-center justify-between pb-2 border-b border-gray-200 dark:border-[#1f1f29]">
                        <span class="font-bold text-navy-700 dark:text-white uppercase tracking-wider flex items-center gap-2">
                            <span class="w-2 h-2 rounded-full ${this.isExactMode ? 'bg-purple-400' : 'bg-emerald-400'}"></span>
                            Division Evaluation Mode: ${this.isExactMode ? 'Exact Division (R ÷_exact S)' : 'Standard Division (R ÷ S)'}
                        </span>
                        <span class="text-[11px] font-bold px-2.5 py-0.5 rounded-full ${this.isExactMode ? 'bg-purple-500/20 text-[#C0B8FE] border border-purple-500/30' : 'bg-green-500/15 text-emerald-400 border border-emerald-500/20'}">
                            ${this.isExactMode ? 'STRICT BIJECTION (NO EXTRAS)' : 'SUPERSETS PERMITTED'}
                        </span>
                    </div>
                    <div class="space-y-2 pt-1">
                `;

                universalQualifiers.forEach(c => {
                    const candidateName = c.candidate[candidateAttrs[1]] || c.candidate[candidateAttrs[0]];
                    const extraList = c.extraItems.map(item => Object.values(item).join(':')).join(', ');
                    
                    if (this.isExactMode) {
                        if (c.isExactQualified) {
                            auditHtml += `
                                <div class="flex items-center justify-between p-2.5 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-emerald-300">
                                    <div class="flex items-center gap-2">
                                        <span class="font-bold text-emerald-400 text-sm">✓</span>
                                        <span><strong>${candidateName}</strong>: completed all ${c.matchedCount}/${c.totalRequired} requirements, 0 extra items</span>
                                    </div>
                                    <span class="font-bold uppercase text-[10px] px-2.5 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">Exact Qualified</span>
                                </div>
                            `;
                        } else {
                            auditHtml += `
                                <div class="flex items-center justify-between p-2.5 rounded-lg bg-red-500/15 border border-red-500/30 text-red-300">
                                    <div class="flex items-center gap-2">
                                        <span class="font-bold text-red-400 text-sm">✕</span>
                                        <span><strong>${candidateName}</strong>: completed ${c.matchedCount}/${c.totalRequired} requirements, but possesses extra item(s): <span class="underline font-bold text-red-200">${extraList}</span></span>
                                    </div>
                                    <span class="font-bold uppercase text-[10px] px-2.5 py-0.5 rounded bg-red-500/25 text-red-300 border border-red-500/30">Eliminated (Extra Tuples)</span>
                                </div>
                            `;
                        }
                    } else {
                        if (c.isExactQualified) {
                            auditHtml += `
                                <div class="flex items-center justify-between p-2.5 rounded-lg bg-lightPrimary dark:bg-[#111116] text-gray-700 dark:text-gray-300">
                                    <div class="flex items-center gap-2">
                                        <span class="text-emerald-400 font-bold text-sm">✓</span>
                                        <span><strong>${candidateName}</strong>: completed all ${c.matchedCount}/${c.totalRequired} requirements (0 extra items)</span>
                                    </div>
                                    <span class="text-[10px] px-2.5 py-0.5 rounded bg-green-500/10 text-emerald-400 font-bold">Qualified</span>
                                </div>
                            `;
                        } else {
                            auditHtml += `
                                <div class="flex items-center justify-between p-2.5 rounded-lg bg-amber-500/10 border border-amber-500/20 text-amber-300">
                                    <div class="flex items-center gap-2">
                                        <span class="font-bold text-amber-400 text-sm">✓</span>
                                        <span><strong>${candidateName}</strong>: completed ${c.matchedCount}/${c.totalRequired} requirements + extra item(s): <span class="font-bold text-amber-200">${extraList}</span></span>
                                    </div>
                                    <span class="text-[10px] px-2.5 py-0.5 rounded bg-amber-500/20 text-amber-300 font-bold border border-amber-500/30">Qualified (Superset Allowed)</span>
                                </div>
                            `;
                        }
                    }
                });

                if (universalQualifiers.length === 0) {
                    auditHtml += `<div class="text-gray-500 py-1">No candidates qualified 100% of divisor criteria.</div>`;
                }

                auditHtml += `</div>`;
                elExactAudit.innerHTML = auditHtml;
            }

            const cT1 = document.getElementById('step-count-t1');
            const tT1 = document.getElementById('step-table-t1');
            if (cT1) cT1.textContent = `${T1.cardinality} candidates`;
            if (tT1) tT1.innerHTML = Visualizer.renderTableHTML(T1);

            const cT2 = document.getElementById('step-count-t2');
            const tT2 = document.getElementById('step-table-t2');
            if (cT2) cT2.textContent = `${T2.cardinality} pairs`;
            if (tT2) tT2.innerHTML = Visualizer.renderTableHTML(T2);

            const cT3 = document.getElementById('step-count-t3');
            const tT3 = document.getElementById('step-table-t3');
            if (cT3) cT3.textContent = `${T3.cardinality} missing`;
            if (tT3) tT3.innerHTML = Visualizer.renderTableHTML(T3);

            const cT4 = document.getElementById('step-count-t4');
            const tT4 = document.getElementById('step-table-t4');
            if (cT4) cT4.textContent = `${T4.cardinality} disqualified`;
            if (tT4) tT4.innerHTML = Visualizer.renderTableHTML(T4);

            const cTracer = document.getElementById('container-tracer');
            const cDag = document.getElementById('container-dag');
            if (cTracer) Visualizer.renderTracer(cTracer, candidateAudit, this.relationS);
            if (cDag) Visualizer.renderDAG(cDag, this.executionTrace, this.isExactMode);

            this.sqlObj = SQLGenerator.generateAll(this.relationR, this.relationS, candidateAttrs, divisorAttrs);
            const elRa = document.getElementById('code-ra');
            const elTrc = document.getElementById('code-trc');
            const elDrc = document.getElementById('code-drc');
            const elNotExists = document.getElementById('code-notexists');
            const elGroupBy = document.getElementById('code-groupby');
            const elExcept = document.getElementById('code-except');
            const elExact = document.getElementById('code-exact');

            if (elRa && this.sqlObj.relationalAlgebra) {
                elRa.textContent = `${this.sqlObj.relationalAlgebra.formula}\n\n-- 5-Stage Operator Pipeline Decomposition:\n${this.sqlObj.relationalAlgebra.steps}`;
            }
            if (elTrc && this.sqlObj.tupleCalculus) {
                elTrc.textContent = `${this.sqlObj.tupleCalculus.formula}\n\n-- Computationally Safe Relational Form (De Morgan Equivalence):\n${this.sqlObj.tupleCalculus.safeNegationFormula}`;
            }
            if (elDrc && this.sqlObj.domainCalculus) {
                elDrc.textContent = `${this.sqlObj.domainCalculus.formula}\n\n-- Domain Independent Implication Form:\n${this.sqlObj.domainCalculus.safeNegationFormula}`;
            }
            if (elNotExists) elNotExists.textContent = this.sqlObj.doubleNotExists.sql;
            if (elGroupBy) elGroupBy.textContent = this.sqlObj.groupByHaving.sql;
            if (elExcept) elExcept.textContent = this.sqlObj.setDifference.sql;
            if (elExact && this.sqlObj.exactDivision) elExact.textContent = this.sqlObj.exactDivision.sql;

            this.updateCoverageMatrix();

            if (typeof renderMathInElement !== 'undefined') {
                try {
                    renderMathInElement(document.body, {delimiters: [{left: '$$', right: '$$', display: true}, {left: '$', right: '$', display: false}]});
                } catch (e) {}
            }

            this.terminal.log(`Pipeline executed in ${elapsed}ms. Candidates: ${metrics.totalCandidates}, Qualified: ${qualCount}`, 'success');

        } catch (err) {
            this.terminal.log(`Execution Error: ${err.message}`, 'error');
            if (typeof toast !== 'undefined') toast.error(err.message);
        }
    }

    updateCoverageMatrix() {
        if (!this.executionTrace) return;
        const container = document.getElementById('container-matrix');
        if (container) {
            Visualizer.renderCoverageMatrix(container, this.executionTrace.candidateAudit, this.fuzzyThreshold);
        }
    }

    startTelemetryListener() {
    }

    runTests() {
        if (typeof TestSuiteRunner === 'undefined') return;
        const res = TestSuiteRunner.runAll();
        const container = document.getElementById('container-test-results');
        if (!container) return;

        const tabBadgeTests = document.getElementById('tab-badge-tests');
        if (tabBadgeTests) tabBadgeTests.textContent = `${res.passed}/${res.total}`;

        let html = `
            <div class="flex items-center justify-between pb-3 font-mono text-xs text-gray-500 dark:text-gray-400 border-b border-gray-100 dark:border-[#1f1f29]">
                <span class="font-bold text-navy-700 dark:text-white uppercase tracking-wider">Formal Verification: 8 Invariant Benchmarks</span>
                <span class="px-3 py-1 rounded-full text-xs font-bold bg-green-500/10 text-[#05CD99] border border-[#05CD99]/20">
                    ${res.passed} / 8 Passed (${res.passRate}%) in ${res.totalDurationMs}ms
                </span>
            </div>
        `;

        res.results.forEach(t => {
            html += `
                <div class="p-3.5 rounded-2xl bg-lightPrimary/70 dark:bg-[#111116] border border-gray-100 dark:border-[#1f1f29] flex items-center justify-between hover:border-[#7551FF]/40 hover:bg-[#14141c] transition-all">
                    <div class="space-y-0.5">
                        <div class="flex items-center gap-2">
                            <span class="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-brand-50 text-brand-500 dark:bg-[#7551FF]/20 dark:text-[#A195FD] border dark:border-[#7551FF]/30">${t.id}</span>
                            <span class="text-xs font-bold text-navy-700 dark:text-white">${t.name}</span>
                        </div>
                        <div class="text-[11px] text-gray-500 dark:text-gray-400 font-mono pl-0.5">${t.details}</div>
                    </div>
                    <span class="px-3 py-1 rounded-full text-xs font-bold font-mono ${t.passed ? 'bg-[#05CD99]/15 text-[#05CD99] border border-[#05CD99]/30' : 'bg-[#EE5D50]/15 text-[#EE5D50] border border-[#EE5D50]/30'} flex-shrink-0 ml-3">
                        ${t.passed ? '✓ PASS' : '✕ FAIL'}
                    </span>
                </div>
            `;
        });

        container.innerHTML = html;
        this.terminal.log(`Formal verification suite executed: ${res.passed}/${res.total} boundary invariants verified in ${res.totalDurationMs}ms.`, 'success');
    }
}

let simApp;
window.addEventListener('DOMContentLoaded', () => {
    simApp = new SimWorkspace();
    window.simApp = simApp;
});